import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long k = nextLong();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nextInt();
        // compress values so counts fit in an array
        int[] vals = a.clone();
        Arrays.sort(vals);
        int u = 0;
        for (int i = 0; i < n; i++) if (i == 0 || vals[i] != vals[i - 1]) vals[u++] = vals[i];
        int[] id = new int[n];
        for (int i = 0; i < n; i++) id[i] = Arrays.binarySearch(vals, 0, u, a[i]);
        long[] cnt = new long[u];
        long pairs = 0, answer = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            pairs += cnt[id[right]]++;
            // once [left, right] has k pairs, every longer window from left does too
            while (pairs >= k) {
                answer += n - right;
                pairs -= --cnt[id[left]];
                left++;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, k := readInt(), readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	counts := make(map[int]int, n)
	pairs, answer, left := 0, 0, 0
	for right, v := range a {
		pairs += counts[v]
		counts[v]++
		// once [left, right] has k pairs, every longer window from left does too
		for pairs >= k {
			answer += n - right
			counts[a[left]]--
			pairs -= counts[a[left]]
			left++
		}
	}
	fmt.Println(answer)
}
